.koha-return-library {
            margin-top: 4px;
            font-size: .88em;
            line-height: 1.3;
            color: #4d5965;
        }
        .koha-return-library strong {
            color: #245f86;
            font-weight: 650;
        }
        .koha-return-library::before {
            content: "↳ ";
            color: #6b7785;
        }

        .krt-panel {
            margin: 18px 0;
            border: 1px solid #d6dde3;
            border-radius: 10px;
            background: #fff;
            box-shadow: 0 1px 3px rgba(0,0,0,.06);
            overflow: hidden;
        }
        .krt-header {
            display: flex;
            align-items: flex-start;
            justify-content: space-between;
            gap: 16px;
            padding: 14px 16px 12px;
            border-bottom: 1px solid #e6eaee;
            background: #f8fafb;
        }
        .krt-title-wrap {
            min-width: 0;
        }
        .krt-title {
            margin: 0;
            font-size: 1.12rem;
            font-weight: 700;
            color: #27313a;
        }
        .krt-subtitle {
            margin-top: 3px;
            color: #6b7785;
            font-size: .88rem;
        }
        .krt-collapse {
            flex: 0 0 auto;
            border: 1px solid #cfd7df;
            border-radius: 6px;
            background: #fff;
            color: #384653;
            padding: 5px 9px;
            cursor: pointer;
            font-size: .85rem;
        }
        .krt-body[hidden] {
            display: none !important;
        }

        .krt-summary {
            display: grid;
            grid-template-columns: repeat(4, minmax(120px, 1fr));
            gap: 8px;
            padding: 12px 16px 4px;
        }
        .krt-card {
            border: 1px solid #e3e8ed;
            border-radius: 8px;
            background: #fff;
            padding: 9px 11px;
            min-width: 0;
        }
        .krt-card-value {
            display: block;
            color: #263542;
            font-size: 1.18rem;
            line-height: 1.1;
            font-weight: 750;
        }
        .krt-card-label {
            display: block;
            margin-top: 3px;
            color: #73808c;
            font-size: .78rem;
            line-height: 1.2;
        }

        .krt-toolbar {
            display: flex;
            flex-wrap: wrap;
            align-items: center;
            justify-content: space-between;
            gap: 8px 14px;
            padding: 10px 16px 12px;
        }
        .krt-filter {
            display: flex;
            align-items: center;
            gap: 6px;
            flex: 1 1 280px;
            max-width: 460px;
        }
        .krt-filter-input {
            width: 100%;
            min-width: 180px;
            border: 1px solid #cfd7df;
            border-radius: 6px;
            background: #fff;
            color: #263542;
            padding: 6px 9px;
            font-size: .84rem;
        }
        .krt-filter-input:focus {
            outline: 2px solid rgba(36,95,134,.18);
            border-color: #245f86;
        }
        .krt-filter-clear {
            flex: 0 0 auto;
            border: 1px solid #cfd7df;
            border-radius: 6px;
            background: #fff;
            color: #53616d;
            padding: 5px 8px;
            cursor: pointer;
            font-size: .82rem;
        }
        .krt-filter-clear:hover {
            background: #f3f6f8;
        }
        .krt-toolbar-right {
            display: flex;
            flex-wrap: wrap;
            align-items: center;
            justify-content: flex-end;
            gap: 8px 14px;
        }
        .krt-range-buttons {
            display: flex;
            flex-wrap: wrap;
            gap: 5px;
        }
        .krt-range-button {
            border: 1px solid #cfd7df;
            border-radius: 6px;
            background: #fff;
            color: #34424f;
            padding: 5px 9px;
            cursor: pointer;
            font-size: .82rem;
        }
        .krt-range-button:hover {
            background: #f3f6f8;
        }
        .krt-range-button.is-active {
            border-color: #245f86;
            background: #245f86;
            color: #fff;
        }
        .krt-legend {
            display: flex;
            flex-wrap: wrap;
            gap: 10px;
            color: #66737f;
            font-size: .78rem;
        }
        .krt-legend-item {
            white-space: nowrap;
        }
        .krt-legend-dot,
        .krt-legend-line {
            display: inline-block;
            vertical-align: middle;
            margin-right: 4px;
        }
        .krt-legend-dot {
            width: 9px;
            height: 9px;
            border-radius: 50%;
            background: #2f78a8;
        }
        .krt-legend-line {
            width: 19px;
            height: 4px;
            border-radius: 3px;
            background: #2f78a8;
        }
        .krt-legend-line.is-active {
            background: repeating-linear-gradient(90deg,#2f78a8 0 6px,transparent 6px 10px);
        }
        .krt-legend-line.is-cross {
            background: #b26a16;
        }

        .krt-scroll {
            overflow-x: auto;
            padding: 0 16px 14px;
        }
        .krt-chart {
            min-width: 980px;
        }
        .krt-axis,
        .krt-row {
            display: grid;
            grid-template-columns: 220px minmax(760px, 1fr);
        }
        .krt-axis {
            position: sticky;
            top: 0;
            z-index: 4;
            background: #fff;
            border-top: 1px solid #edf0f2;
            border-bottom: 1px solid #dfe5ea;
        }
        .krt-axis-label {
            padding: 10px 10px 8px 2px;
            color: #65727e;
            font-size: .76rem;
            font-weight: 650;
        }
        .krt-axis-track {
            position: relative;
            height: 38px;
        }
        .krt-tick {
            position: absolute;
            top: 0;
            bottom: 0;
            width: 1px;
            background: #e3e8ec;
        }
        .krt-tick-label {
            position: absolute;
            top: 8px;
            transform: translateX(-50%);
            white-space: nowrap;
            color: #66737f;
            font-size: .72rem;
        }
        .krt-tick-label.is-first {
            transform: none;
        }
        .krt-tick-label.is-last {
            transform: translateX(-100%);
        }

        .krt-row {
            min-height: 54px;
            border-bottom: 1px solid #eef1f4;
        }
        .krt-row:last-child {
            border-bottom: 0;
        }
        .krt-row-label {
            padding: 8px 12px 7px 2px;
            min-width: 0;
        }
        .krt-row-main {
            display: block;
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
            font-size: .84rem;
            font-weight: 650;
            color: #263542;
        }
        .krt-row-sub {
            display: block;
            margin-top: 2px;
            overflow: hidden;
            text-overflow: ellipsis;
            white-space: nowrap;
            font-size: .72rem;
            color: #74818c;
        }
        .krt-track {
            position: relative;
            min-height: 54px;
            background-image: linear-gradient(to bottom, transparent 26px, #f1f3f5 27px, transparent 28px);
        }
        .krt-grid-line {
            position: absolute;
            top: 0;
            bottom: 0;
            width: 1px;
            background: #f0f2f4;
            pointer-events: none;
        }

        .krt-event {
            position: absolute;
            top: 17px;
            height: 20px;
            min-width: 4px;
            cursor: help;
        }
        .krt-event-line {
            position: absolute;
            left: 0;
            right: 0;
            top: 8px;
            height: 5px;
            border-radius: 4px;
            background: #2f78a8;
            opacity: .88;
        }
        .krt-event.is-cross .krt-event-line {
            background: #b26a16;
        }
        .krt-event.is-current .krt-event-line {
            background: repeating-linear-gradient(90deg,#2f78a8 0 8px,transparent 8px 12px);
        }
        .krt-event-start,
        .krt-event-end {
            position: absolute;
            top: 4px;
            width: 12px;
            height: 12px;
            border: 2px solid #fff;
            border-radius: 50%;
            background: #2f78a8;
            box-shadow: 0 0 0 1px #2f78a8;
        }
        .krt-event.is-cross .krt-event-end {
            background: #b26a16;
            box-shadow: 0 0 0 1px #b26a16;
        }
        .krt-event-start {
            left: -5px;
        }
        .krt-event-end {
            right: -5px;
        }
        .krt-event.is-current .krt-event-end {
            width: 0;
            height: 0;
            top: 2px;
            right: -3px;
            border-radius: 0;
            border-top: 8px solid transparent;
            border-bottom: 8px solid transparent;
            border-left: 10px solid #2f78a8;
            border-right: 0;
            background: transparent;
            box-shadow: none;
        }
        .krt-renewal {
            position: absolute;
            top: -7px;
            transform: translateX(-50%);
            color: #6b4f9d;
            font-size: .82rem;
            font-weight: 800;
            line-height: 1;
        }
        .krt-event-site {
            position: absolute;
            top: 20px;
            white-space: nowrap;
            font-size: .67rem;
            color: #66737f;
        }
        .krt-event-site.is-start {
            left: -4px;
        }
        .krt-event-site.is-end {
            right: -4px;
            text-align: right;
        }
        .krt-event-warning {
            position: absolute;
            top: -8px;
            right: -8px;
            font-size: .72rem;
            line-height: 1;
        }

        .krt-empty,
        .krt-limit-note {
            padding: 14px 16px;
            color: #6a7681;
            font-size: .84rem;
        }
        .krt-limit-note {
            padding-top: 6px;
            border-top: 1px solid #edf0f2;
            background: #fafbfc;
        }

        .krt-tooltip {
            position: fixed;
            z-index: 99999;
            max-width: 330px;
            pointer-events: none;
            border: 1px solid rgba(20,32,42,.15);
            border-radius: 7px;
            background: rgba(30,39,47,.96);
            color: #fff;
            padding: 8px 10px;
            box-shadow: 0 5px 18px rgba(0,0,0,.22);
            font-size: .76rem;
            line-height: 1.45;
            white-space: pre-line;
        }
        .krt-tooltip[hidden] {
            display: none !important;
        }


        .krt-point {
            position: absolute;
            top: 7px;
            width: 14px;
            height: 14px;
            transform: translateX(-50%);
            border: 2px solid #fff;
            border-radius: 50%;
            box-shadow: 0 0 0 1px currentColor;
            cursor: help;
            z-index: 3;
        }
        .krt-point.is-acquisition { color:#568132; background:#568132; }
        .krt-point.is-transfer { color:#4b78a0; background:#4b78a0; border-radius:3px; transform:translateX(-50%) rotate(45deg); }
        .krt-point.is-seen { color:#7a6597; background:#7a6597; }
        .krt-point.is-cancelled { color:#a24e47; background:#a24e47; }

        @media (max-width: 900px) {
            .krt-summary {
                grid-template-columns: repeat(2, minmax(120px, 1fr));
            }
            .krt-header {
                align-items: center;
            }
        }

