                gap: 8px;
                font-size: 12px;
                font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
                color: #adb5bd;
            }

            #koha-quagga-status-dot {
                width: 8px;
                height: 8px;
                border-radius: 50%;
                background: #6c757d;
                display: inline-block;
                transition: background 0.3s;
            }

            #koha-quagga-status-dot.scanning {
                background: #ffc107;
                animation: pulse-dot 0.8s ease-in-out infinite;
            }

            #koha-quagga-status-dot.detected {
                background: #28a745;
            }

            #koha-quagga-status-dot.error {
                background: #dc3545;
            }

            #koha-quagga-status-dot.verifying {
                background: #17a2b8;
                animation: pulse-dot 0.4s ease-in-out infinite;
            }

            @keyframes pulse-dot {
                0%, 100% { opacity: 1; transform: scale(1); }
                50% { opacity: 0.4; transform: scale(0.8); }
            }

            /* === Résolution affichée === */
            #koha-quagga-resolution {
                font-size: 11px;
                color: #6c757d;
                font-family: monospace;
                margin-left: 4px;
            }

            /* === Vidéo === */
            #koha-quagga-video {
                flex: 1;
                min-height: 0;
                width: 100%;
                object-fit: cover;
                background: #000;
            }

            /* === Message === */
            #koha-quagga-msg {
                padding: 10px 16px 16px;
                color: #adb5bd;
                text-align: center;
