            }

            #koha-quagga-msg strong {
                color: #e9ecef;
                font-weight: 500;
            }

            #koha-quagga-msg .highlight {
                color: #ffc107;
            }

            #koha-quagga-msg .progress {
                color: #17a2b8;
            }

            /* === Cache le canvas de Quagga === */
            #koha-quagga-overlay canvas.drawingBuffer {
                display: none !important;
