:root {
                --kx-list-green: #4f772d;
                --kx-list-green-dark: #365314;
                --kx-list-green-soft: #f3f7ef;
                --kx-list-border: #d9dfe3;
                --kx-list-text: #27313a;
                --kx-list-muted: #6b7280;
                --kx-list-danger: #b42318;
            }

            #kx-temp-lists-panel {
                position: fixed;
                z-index: 10050;
                top: 0;
                right: 0;
                width: min(430px, 94vw);
                height: 100vh;
                height: 100dvh;
                box-sizing: border-box;
                display: flex;
                flex-direction: column;
                background: #fff;
                color: var(--kx-list-text);
                border-left: 1px solid var(--kx-list-border);
                box-shadow: -10px 0 30px rgba(30, 41, 59, .16);
                transform: translateX(105%);
                transition: transform .22s ease;
                font-family: inherit;
            }

            #kx-temp-lists-panel.is-open {
                transform: translateX(0);
            }

            #kx-temp-lists-panel .kx-tl-header {
                display: flex;
                align-items: center;
                gap: 10px;
                padding: 14px 14px 12px;
                background: linear-gradient(135deg, var(--kx-list-green), var(--kx-list-green-dark));
                color: #fff;
            }

            #kx-temp-lists-panel .kx-tl-header-main {
                min-width: 0;
                flex: 1;
            }

            #kx-temp-lists-panel .kx-tl-title {
                margin: 0;
                font-size: 18px;
                font-weight: 800;
                line-height: 1.2;
                color: #fff !important;
                text-shadow: 0 1px 2px rgba(0,0,0,.22);
            }

            #kx-temp-lists-panel .kx-tl-subtitle {
                margin-top: 4px;
                font-size: 12px;
                font-weight: 600;
                line-height: 1.3;
                color: #fff !important;
                opacity: 1;
                text-shadow: 0 1px 1px rgba(0,0,0,.16);
            }

            #kx-temp-lists-panel .kx-tl-close {
                width: 34px;
                height: 34px;
                flex: 0 0 34px;
                display: inline-flex;
                align-items: center;
                justify-content: center;
                border: 1px solid rgba(255,255,255,.28);
                border-radius: 8px;
                background: rgba(255,255,255,.12);
                color: #fff;
                cursor: pointer;
                font-size: 20px;
            }

            #kx-temp-lists-panel .kx-tl-close:hover {
                background: rgba(255,255,255,.22);
            }

            #kx-temp-lists-panel .kx-tl-tabs {
                display: grid;
                grid-template-columns: 1fr 1fr;
                padding: 10px 10px 0;
                gap: 6px;
                background: #fff;
            }

            #kx-temp-lists-panel .kx-tl-tab {
                display: flex;
                align-items: center;
                justify-content: center;
                gap: 7px;
                padding: 9px 10px;
                border: 1px solid var(--kx-list-border);
                border-radius: 8px 8px 0 0;
                background: #f8fafc;
                color: #475569;
                cursor: pointer;
                font-weight: 650;
            }

            #kx-temp-lists-panel .kx-tl-tab.is-active {
                background: var(--kx-list-green-soft);
                color: var(--kx-list-green-dark);
                border-bottom-color: var(--kx-list-green-soft);
            }

            #kx-temp-lists-panel .kx-tl-count {
                min-width: 22px;
                height: 22px;
                padding: 0 6px;
                display: inline-flex;
                align-items: center;
                justify-content: center;
                box-sizing: border-box;
                border-radius: 999px;
                background: #e2e8f0;
                color: #334155;
                font-size: 11px;
                font-weight: 700;
            }

            #kx-temp-lists-panel .kx-tl-tab.is-active .kx-tl-count {
                background: var(--kx-list-green);
                color: #fff;
            }

            #kx-temp-lists-panel .kx-tl-pane {
                display: none;
                flex: 1;
                min-height: 0;
                flex-direction: column;
                padding: 10px;
                background: #f8fafc;
                border-top: 1px solid var(--kx-list-border);
            }

            #kx-temp-lists-panel .kx-tl-pane.is-active {
                display: flex;
            }

            #kx-temp-lists-panel .kx-tl-search {
                width: 100%;
                box-sizing: border-box;
                margin: 0 0 8px;
                padding: 8px 10px;
                border: 1px solid #cbd5e1;
                border-radius: 7px;
                background: #fff;
                color: #1f2937;
            }

            #kx-temp-lists-panel .kx-tl-actions {
                display: grid;
                grid-template-columns: 1fr 1fr;
                gap: 6px;
                margin-bottom: 9px;
            }

            #kx-temp-lists-panel .kx-tl-action {
                min-height: 34px;
                display: inline-flex;
                align-items: center;
                justify-content: center;
                gap: 6px;
                border: 1px solid #cbd5e1;
                border-radius: 7px;
                background: #fff;
                color: #334155;
                cursor: pointer;
                font-size: 12px;
                font-weight: 600;
                text-align: center;
            }

            #kx-temp-lists-panel .kx-tl-action:hover {
                border-color: #94a3b8;
                background: #f1f5f9;
            }

            #kx-temp-lists-panel .kx-tl-action.is-danger {
                color: var(--kx-list-danger);
                border-color: #f2c8c4;
                background: #fff8f7;
            }

            #kx-temp-lists-panel .kx-tl-action.is-wide {
                grid-column: 1 / -1;
            }

            #kx-temp-lists-panel .kx-transfer-manager {
                display: grid;
                grid-template-columns: auto auto auto minmax(100px, 1fr) auto auto;
                align-items: center;
                gap: 6px;
                margin: 0 0 9px;
                padding: 7px;
                border: 1px solid #dbe3e8;
                border-radius: 8px;
                background: #fff;
            }

            #kx-temp-lists-panel .kx-transfer-count {
                min-width: 76px;
                color: #475569;
                font-size: 11px;
                font-weight: 700;
                white-space: nowrap;
            }

            #kx-temp-lists-panel .kx-transfer-manager select {
                min-width: 0;
                width: 100%;
                height: 32px;
                padding: 4px 7px;
                border: 1px solid #cbd5e1;
                border-radius: 6px;
                background: #fff;
                color: #334155;
                font-size: 11px;
            }

            #kx-temp-lists-panel .kx-transfer-btn {
                min-height: 32px;
                padding: 4px 8px;
                border: 1px solid #cbd5e1;
                border-radius: 6px;
                background: #fff;
                color: #334155;
                cursor: pointer;
                font-size: 11px;
                font-weight: 650;
                white-space: nowrap;
            }

            #kx-temp-lists-panel .kx-transfer-btn:hover:not(:disabled) {
                background: #f1f5f9;
                border-color: #94a3b8;
            }

            #kx-temp-lists-panel .kx-transfer-btn:disabled,
            #kx-temp-lists-panel .kx-transfer-manager select:disabled {
                opacity: .5;
                cursor: not-allowed;
            }

            #kx-temp-lists-panel .kx-transfer-btn.is-primary {
                border-color: #b9cda9;
                background: var(--kx-list-green-soft);
                color: var(--kx-list-green-dark);
            }

            #kx-temp-lists-panel .kx-tl-card.is-selected {
                border-color: #9dbb85;
                background: #fbfdf9;
            }

            #kx-temp-lists-panel .kx-tl-select-wrap {
                flex: 0 0 20px;
                display: flex;
                align-items: flex-start;
                justify-content: center;
                padding-top: 2px;
            }

            #kx-temp-lists-panel .kx-tl-select {
                width: 17px;
                height: 17px;
                margin: 0;
                accent-color: var(--kx-list-green);
                cursor: pointer;
            }

            #kx-temp-lists-panel .kx-tl-list {
                flex: 1;
                min-height: 0;
                overflow-y: auto;
                padding-right: 2px;
            }

            #kx-temp-lists-panel .kx-tl-empty {
                margin: 22px 8px;
                padding: 22px 14px;
                border: 1px dashed #cbd5e1;
                border-radius: 10px;
                background: #fff;
                text-align: center;
                color: var(--kx-list-muted);
                font-size: 13px;
            }

            #kx-temp-lists-panel .kx-tl-card {
                display: flex;
                gap: 10px;
                position: relative;
                margin-bottom: 7px;
                padding: 10px 35px 10px 10px;
                border: 1px solid var(--kx-list-border);
                border-radius: 9px;
                background: #fff;
                box-shadow: 0 1px 2px rgba(15,23,42,.03);
            }

            #kx-temp-lists-panel .kx-tl-cover {
                width: 36px;
                height: 50px;
                flex: 0 0 36px;
                object-fit: cover;
                align-self: flex-start;
                border: 1px solid #e2e8f0;
                border-radius: 4px;
                background: #f8fafc;
            }

            #kx-temp-lists-panel .kx-tl-card-body {
                min-width: 0;
                flex: 1;
            }

            #kx-temp-lists-panel .kx-tl-card-title {
                display: block;
                margin: 0 0 4px;
                color: var(--kx-list-green-dark);
                font-weight: 700;
